ruleContent.content:
@js:
int=parseInt(title.match(/第(\d+)/)[1])*10
nt=int-10,u=[]
h=java.get("h").match(/".*?"/g)
while(nt<int)
{
	if(nt<h.length)
	{
		u.push("<img src="+h[nt]+">")
	}
	nt++
}
u.join("\n")

