ruleToc.preUpdateJs:
if (!String(book.bookUrl).includes(Get('url'))) {
    if (/www\./.test(Get('url')) && !/www\./.test(String(book.bookUrl))) {
        book.bookUrl = String(book.bookUrl).replace(/\/api\/v3\/comic2\//, '/comic/');
        book.tocUrl = String(book.tocUrl).replace(/\/api\/v3\/comic2\//, '/comicdetail/').replace(/\/group\/.*$/, '/chapters');
    }
    if (!/www\./.test(Get('url')) && /www\./.test(String(book.bookUrl))) {
        book.bookUrl = String(book.bookUrl).replace(/\/comic\//, '/api/v3/comic2/');
        book.tocUrl = String(book.tocUrl).replace(/\/comic\//, '/api/v3/comic2/').replace(/\/chapters$/, '/group/' + java.get("group") + '/chapters?limit=500&offset=0&_update=true');
    }
    book.bookUrl = String(book.bookUrl).replace(/.*\/\/[^\/]+/, Get('url'));
    book.tocUrl = String(book.tocUrl).replace(/.*\/\/[^\/]+/, Get('url'));
    java.refreshTocUrl();
}

